<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {request,setToken} from './api'
const user=ref(null),group=ref(null),members=ref([]),discussions=ref([]),tab=ref('groups'),joined=ref(false),error=ref(''),busy=ref(false),modal=ref(''),register=ref(false)
const form=ref({email:'',password:'',nickname:'',join_key:'',host_name:'我的学习设备',title:'',body:''})
const online=computed(()=>members.value.filter(m=>m.online).length)
async function run(fn){error.value='';busy.value=true;try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function authenticate(){await run(async()=>{if(register.value)await request('identity','/auth/register','POST',form.value);const data=await request('identity','/auth/login','POST',form.value);setToken(data.access_token);user.value=data.user;form.value.password='';modal.value='';await restoreGroup()})}
async function restoreGroup(){try{await request('group','/group/heartbeat','POST');joined.value=true;await refresh()}catch{joined.value=false;members.value=[];discussions.value=[]}}
async function join(){await run(async()=>{await request('group','/group/join','POST',{...form.value,nickname:user.value.nickname});joined.value=true;form.value.join_key='';modal.value='';tab.value='discussion';await refresh()})}
async function refresh(){if(!joined.value)return;await request('group','/group/heartbeat','POST');const [m,d]=await Promise.all([request('group','/group/members'),request('group','/group/discussions')]);members.value=m;discussions.value=d}
async function publish(){await run(async()=>{await request('group','/group/discussions','POST',{title:form.value.title,body:form.value.body});form.value.title='';form.value.body='';modal.value='';await refresh()})}
function enter(){if(!user.value){modal.value='auth';return}if(!joined.value){modal.value='join';return}tab.value='discussion';run(refresh)}
function logout(){setToken('');user.value=null;joined.value=false;members.value=[];discussions.value=[];tab.value='groups'}
let interval
onMounted(async()=>{await run(async()=>{group.value=await request('group','/group');try{user.value=await request('identity','/users/me');await restoreGroup()}catch{setToken('')}});interval=setInterval(()=>{if(!document.hidden&&joined.value)run(refresh)},30000)})
onUnmounted(()=>clearInterval(interval))
</script>
<template>
 <aside><a class="brand">◈ 算法同行<small>ALGO TOGETHER</small></a><p class="label">学习空间</p><button :class="{active:tab==='groups'}" @click="tab='groups'">◇ 群组入口</button><button :class="{active:tab==='discussion'}" @click="tab='discussion'">☷ 群组讨论</button><button :class="{active:tab==='members'}" @click="tab='members'">◎ 联网成员</button><div class="aside-note">Spring Boot + Vue 3<small>独立群组服务 · 第一阶段</small></div></aside>
 <main><header><span>社区 / {{ {groups:'群组入口',discussion:'群组讨论',members:'联网成员'}[tab] }}</span><div><span>{{user?.nickname||'尚未登录'}}</span><button class="secondary" @click="user?logout():modal='auth'">{{user?'退出登录':'登录 / 注册'}}</button></div></header>
 <div class="hero"><small>LEARN · SHARE · GROW</small><h1>{{tab==='groups'?'找到你的算法同伴':tab==='discussion'?'把思考分享给同伴':'同伴就在这里'}}</h1><p>让每一个独立学习的时刻，都有同伴同行。</p></div>
 <p v-if="error" class="error" role="alert">{{error}}</p>
 <div v-if="joined" class="status">当前群组：{{group?.name}} <span>{{online}} 人在线</span><button class="secondary" :disabled="busy" @click="run(refresh)">同步成员</button></div>
 <section v-if="tab==='groups'"><h2>可连接的群组</h2><article v-if="group" class="card"><div class="icon">⌘</div><h3>{{group.name}}</h3><p>连接当前群组服务，用独立的成员身份加入算法学习讨论。</p><div class="bottom"><span class="badge">{{joined?'已加入':'密钥加入'}}</span><button @click="enter">{{joined?'进入群组 →':'连接群组 →'}}</button></div></article><div v-else class="empty">尚未连接群组服务，请检查后端是否启动。</div><p class="note">这一阶段已分离身份与群组数据库。节点自动复制、离线缓存与跨公网部署仍在后续实现范围内。</p></section>
 <section v-if="tab==='discussion'"><div class="section-head"><h2>交流与复盘</h2><button v-if="joined" @click="modal='post'">＋ 发布讨论</button></div><div v-if="!joined" class="empty">先从群组入口加入一个群组。</div><div v-else-if="!discussions.length" class="empty">分享一个算法疑问，开始第一场讨论。</div><article v-for="post in discussions" :key="post.id" class="card post"><span class="muted">{{post.nickname}} · {{new Date(post.created_at).toLocaleString('zh-CN')}}</span><h3>{{post.title}}</h3><p>{{post.body}}</p></article></section>
 <section v-if="tab==='members'"><h2>联网成员</h2><div v-if="!joined" class="empty">加入群组后查看同伴。</div><div v-for="member in members" :key="member.user_id" class="member"><span class="avatar">{{member.nickname.slice(0,1)}}</span><div><strong>{{member.nickname}}</strong><small>{{member.host_name}}</small></div><span :class="['presence',{offline:!member.online}]">{{member.online?'● 在线':'● 离线'}}</span></div><p class="note">30 秒心跳同步，90 秒未收到心跳后显示离线。</p></section>
 <footer>算法同行 · 目标驱动的算法学习社区</footer></main>
 <div v-if="modal" class="overlay"><div class="dialog" role="dialog" aria-modal="true"><div class="section-head"><h2>{{modal==='auth'?(register?'创建学习账号':'欢迎回来'):modal==='join'?'密钥加入群组':'发布讨论'}}</h2><button class="secondary" @click="modal=''">✕</button></div><form @submit.prevent="modal==='auth'?authenticate():modal==='join'?join():publish()"><template v-if="modal==='auth'"><label>邮箱<input v-model="form.email" type="email" required></label><label>密码<input v-model="form.password" type="password" minlength="8" required></label><label v-if="register">昵称<input v-model="form.nickname" maxlength="40" required></label><button type="button" class="secondary" @click="register=!register">{{register?'已有账号？登录':'还没有账号？注册'}}</button></template><template v-if="modal==='join'"><label>群主分享的联网密钥<input v-model="form.join_key" type="password" minlength="16" required></label><label>设备名称<input v-model="form.host_name" maxlength="80" required></label></template><template v-if="modal==='post'"><label>标题<input v-model="form.title" maxlength="100" required></label><label>内容<textarea v-model="form.body" maxlength="20000" required></textarea></label></template><p v-if="error" class="error">{{error}}</p><button class="submit" :disabled="busy">{{busy?'处理中…':'确认'}}</button></form></div></div>
</template>
